-- Records of system_user_role
-- ----------------------------

-- ----------------------------
-- Table structure for system_users
-- ----------------------------
DROP TABLE IF EXISTS `system_users`;
CREATE TABLE `system_users`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `username` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户账号',
  `password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '密码',
  `nickname` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户昵称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '部门ID',
  `post_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '岗位编号数组',
  `email` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '用户邮箱',
  `mobile` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '手机号码',
  `sex` tinyint NULL DEFAULT 0 COMMENT '用户性别',
  `avatar` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '头像地址',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '帐号状态（0正常 1停用）',
  `login_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '最后登录IP',
  `login_date` datetime NULL DEFAULT NULL COMMENT '最后登录时间',
  `openid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '用户标识',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_username`(`username` ASC, `update_time` ASC, `tenant_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 143 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of system_users
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_achievement
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_achievement`;
CREATE TABLE `yshop_crm_achievement`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  `config` tinyint NOT NULL DEFAULT 1 COMMENT '1销售（目标）2回款（目标）',
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '2员工3部门',
  `type_id` bigint NOT NULL DEFAULT 0 COMMENT '对象ID',
  `year` int NOT NULL COMMENT '年',
  `january` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '一月',
  `february` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '二月',
  `march` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '三月',
  `april` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '四月',
  `may` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '五月',
  `june` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '六月',
  `july` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '七月',
  `august` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '八月',
  `september` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '九月',
  `october` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '十月',
  `november` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '十一月',
  `december` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '十二月',
  `yeartarget` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '年目标',
  `create_time` datetime NULL DEFAULT NULL COMMENT '添加时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '逻辑删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `config`(`config` ASC, `type_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '业绩目标' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_achievement
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_business
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_business`;
CREATE TABLE `yshop_crm_business`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商机名称',
  `status` int NOT NULL DEFAULT 1 COMMENT '销售阶段',
  `status_time` datetime NULL DEFAULT NULL COMMENT '阶段推进时间',
  `is_end` tinyint NOT NULL DEFAULT 0 COMMENT '成交状态0洽淡中，1成交2失败3无效',
  `next_time` datetime NOT NULL COMMENT '下次联系时间',
  `money` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '商机金额',
  `total_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '产品总金额',
  `deal_time` datetime NULL DEFAULT NULL COMMENT '预计成交日期',
  `discount_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '整单折扣',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `owner_user_id` bigint NOT NULL DEFAULT 0 COMMENT '负责人ID',
  `create_time` datetime NULL DEFAULT NULL COMMENT '添加时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '逻辑删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商机表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_business
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_business_product
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_business_product`;
CREATE TABLE `yshop_crm_business_product`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `business_id` bigint NULL DEFAULT 0 COMMENT '商机id',
  `product_id` bigint NOT NULL DEFAULT 0 COMMENT '产品id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品名称',
  `product_attr_unique` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '商品属性',
  `price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '单价',
  `nums` int NULL DEFAULT 0 COMMENT '数量',
  `subtotal` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '小计',
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT NULL COMMENT '添加时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '逻辑删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商机产品关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_business_product
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_clues
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_clues`;
CREATE TABLE `yshop_crm_clues`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '线索',
  `mobile` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机',
  `telephone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电话',
  `status` int NOT NULL DEFAULT 0 COMMENT '状态-1-无效线索，0未转客户,1转成客户',
  `customer_id` bigint NOT NULL DEFAULT 0 COMMENT '转成客户id',
  `change_time` datetime NULL DEFAULT NULL COMMENT '转客户时间',
  `level` int NOT NULL DEFAULT 0 COMMENT '客户级别ID',
  `industry` int NOT NULL DEFAULT 0 COMMENT '客户行业ID',
  `tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT ' 客户标签',
  `source` int NOT NULL DEFAULT 0 COMMENT '客户来源ID',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `owner_user_id` bigint NOT NULL DEFAULT 0 COMMENT '负责人ID',
  `province` int NULL DEFAULT 0 COMMENT '省份id',
  `city` int NULL DEFAULT 0 COMMENT '城市ID',
  `area` int NULL DEFAULT 0 COMMENT '区域ID',
  `detail_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `next_time` datetime NULL DEFAULT NULL COMMENT '下次联系时间',
  `follow_time` datetime NULL DEFAULT NULL COMMENT '最后跟进时间',
  `collect_time` datetime NULL DEFAULT NULL COMMENT '领取时间',
  `follow_status` tinyint(1) NULL DEFAULT 1 COMMENT '跟进状态1|新客\n2|待再次沟通\n3|有意向\n4|已加微信\n5|转商机\n0|无效',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '线索表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_clues
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_contract
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_contract`;
CREATE TABLE `yshop_crm_contract`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `customer_id` bigint NOT NULL DEFAULT 0 COMMENT '客户ID',
  `business_id` bigint NOT NULL DEFAULT 0 COMMENT '商机ID',
  `contacts_id` bigint NOT NULL DEFAULT 0 COMMENT '客户签约人（联系人ID）',
  `source_id` int NULL DEFAULT 0 COMMENT '客户来源ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '合同名称',
  `number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '合同编号',
  `order_time` datetime NULL DEFAULT NULL COMMENT '下单时间',
  `money` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '合同金额',
  `total_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '产品总金额',
  `return_money` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '已收到款项',
  `discount_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '整单折扣',
  `check_status` tinyint NOT NULL DEFAULT 0 COMMENT '0待审核、1审核中、2审核通过、3审核未通过',
  `flow_id` bigint NOT NULL DEFAULT 0 COMMENT '审核流程ID',
  `step_id` bigint NOT NULL DEFAULT 0 COMMENT '审核步骤ID',
  `check_admin_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '已经审批人IDs',
  `flow_admin_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '需要审批的人',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `order_admin_id` bigint NULL DEFAULT 0 COMMENT '公司签约人',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `owner_user_id` bigint NOT NULL DEFAULT 0 COMMENT '负责人ID',
  `next_time` datetime NULL DEFAULT NULL COMMENT '下次联系时间',
  `expire_handle` tinyint NULL DEFAULT 0 COMMENT '0合同过期未处理1已续签2不再合作',
  `invoice_money` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '已开票金额',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '合同表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_contract
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_contract_product
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_contract_product`;
CREATE TABLE `yshop_crm_contract_product`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `contract_id` bigint NOT NULL DEFAULT 0 COMMENT '合同ID',
  `product_id` bigint NOT NULL DEFAULT 0 COMMENT '产品ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品名称',
  `product_attr_unique` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品属性',
  `price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '产品单价',
  `nums` int NOT NULL DEFAULT 0 COMMENT '数量',
  `discount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '折扣',
  `subtotal` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '小计（折扣后价格）',
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT NULL COMMENT '添加时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '逻辑删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 46 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '合同产品关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_contract_product
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_contract_receivables
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_contract_receivables`;
CREATE TABLE `yshop_crm_contract_receivables`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '回款编号',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `contract_id` bigint NOT NULL COMMENT '合同ID',
  `return_time` datetime NULL DEFAULT NULL COMMENT '回款日期',
  `account_id` int NOT NULL COMMENT '收款账户ID',
  `money` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '回款金额',
  `check_status` tinyint NOT NULL DEFAULT 0 COMMENT '0待审核、1审核中、2审核通过、3审核未通过',
  `flow_id` bigint NOT NULL DEFAULT 0 COMMENT '审核流程ID',
  `step_id` bigint NOT NULL DEFAULT 0 COMMENT '审核步骤排序ID',
  `check_admin_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审批人IDs',
  `flow_admin_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '流程审批人ID',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `owner_user_id` bigint NOT NULL DEFAULT 0 COMMENT '负责人ID',
  `order_admin_id` bigint NULL DEFAULT NULL COMMENT '合同签约人',
  `pay_status` tinyint NULL DEFAULT 0 COMMENT '在线支付状态1已付款0未付款',
  `pay_type` tinyint NULL DEFAULT 1 COMMENT '收款方式1默认2在线收款3续费',
  `code_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '支付url',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '创建支付码时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '回款表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_contract_receivables
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_customer
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_customer`;
CREATE TABLE `yshop_crm_customer`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户名称',
  `mobile` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机',
  `telephone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电话',
  `deal_status` int NOT NULL DEFAULT 0 COMMENT '成交状态0未成交1成交',
  `deal_time` datetime NULL DEFAULT NULL COMMENT '成交时间',
  `is_lock` tinyint(1) NULL DEFAULT 0 COMMENT '1锁定',
  `level` int NOT NULL DEFAULT 0 COMMENT '客户级别ID',
  `industry` int NOT NULL DEFAULT 0 COMMENT '客户行业ID',
  `tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT ' 客户标签',
  `source` int NOT NULL DEFAULT 0 COMMENT '客户来源ID',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `user_id` int NULL DEFAULT 0 COMMENT '前台用户ID',
  `owner_user_id` bigint NULL DEFAULT NULL COMMENT '负责人ID',
  `province` int NULL DEFAULT 0 COMMENT '省份id',
  `city` int NULL DEFAULT 0 COMMENT '城市ID',
  `area` int NULL DEFAULT 0 COMMENT '区域ID',
  `address_str` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '地址组合字符串',
  `detail_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `lng` double(14, 11) NULL DEFAULT NULL COMMENT '地理位置经度',
  `lat` double(14, 11) NULL DEFAULT NULL COMMENT '地理位置维度',
  `next_time` datetime NULL DEFAULT NULL COMMENT '下次联系时间',
  `follow_time` datetime NULL DEFAULT NULL COMMENT '最后跟进时间',
  `collect_time` datetime NULL DEFAULT NULL COMMENT '领取时间',
  `weixin` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '微信',
  `qq` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'QQ',
  `purchase_total` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '消费总额',
  `purchase_times` int NULL DEFAULT 0 COMMENT '消费次数',
  `follow_status` tinyint(1) NULL DEFAULT 1 COMMENT '跟进状态1|新客\n2|待再次沟通\n3|有意向\n4|已加微信\n5|转商机\n0|无效',
  `rw_user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '读写权限用户',
  `ro_user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '只读权限用户',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 104 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_customer
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_customer_contacts
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_customer_contacts`;
CREATE TABLE `yshop_crm_customer_contacts`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名',
  `mobile` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机',
  `birthday` date NULL DEFAULT NULL COMMENT '生日',
  `telephone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电话',
  `wechat` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '微信号',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电子邮箱',
  `decision` tinyint NOT NULL DEFAULT -1 COMMENT '是否关键决策人1是0不是-1未知',
  `post` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '职务',
  `sex` tinyint NOT NULL DEFAULT -1 COMMENT '性别0女1男-1未知',
  `detail_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '地址',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `owner_user_id` bigint NULL DEFAULT NULL COMMENT '负责人ID',
  `next_time` datetime NULL DEFAULT NULL COMMENT '下次联系时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 81 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '联系人表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_customer_contacts
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_flow
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_flow`;
CREATE TABLE `yshop_crm_flow`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '审批流名称',
  `category` tinyint(1) NULL DEFAULT 1 COMMENT '流程类型1-固定审批 2-授权审批',
  `types` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关联对象 contract-合同 receivables-回款 invoice-发票',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '流程说明',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态 1启用，0禁用',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '审批流程表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_flow
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_flow_log
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_flow_log`;
CREATE TABLE `yshop_crm_flow_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `flow_id` bigint NOT NULL DEFAULT 0 COMMENT '审批流程ID',
  `types_id` bigint NOT NULL DEFAULT 0 COMMENT '对象ID（如审批类型ID）',
  `admin_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核人',
  `types` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关联对象 contract-合同 receivables-回款 invoice-发票',
  `nickname` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '审核人名称',
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '审核意见',
  `is_end` tinyint NOT NULL DEFAULT 0 COMMENT '1审核结束',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0-待审核 1-审核通过,2-审核拒绝 3-撤销',
  `admin_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `name`(`nickname` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 42 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '审核日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_flow_log
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_flow_step
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_flow_step`;
CREATE TABLE `yshop_crm_flow_step`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `flow_id` bigint NOT NULL DEFAULT 0 COMMENT '审批流程ID',
  `type` tinyint NOT NULL DEFAULT 1 COMMENT '1上级管理员，2指定用户（任意一人）3-指定用户(多人会签)',
  `admin_ids` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审批人ID (使用逗号隔开) ,1,2,',
  `relation` int NOT NULL DEFAULT 1 COMMENT '审批流程顺序',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '审批步骤表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_flow_step
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_invoice
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_invoice`;
CREATE TABLE `yshop_crm_invoice`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `contract_id` bigint NOT NULL COMMENT '合同ID',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `invoice_body` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开票主体',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '开票内容',
  `invoice_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发票抬头',
  `invoice_issue` tinyint NOT NULL DEFAULT 1 COMMENT '抬头类型1企业2个人3事业单位',
  `invoice_type` tinyint NOT NULL DEFAULT 1 COMMENT '1增普2增专',
  `register_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '统一社会信用代码',
  `bank_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开户行名称',
  `bank_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开户账号',
  `money` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '发票税前金额',
  `tax_rate` int NOT NULL DEFAULT 0 COMMENT '税率',
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `email` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接收发票邮箱',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收件人',
  `user_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收件手机',
  `user_address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮寄地址',
  `files` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开票附件',
  `invoice_admin_id` bigint NULL DEFAULT NULL COMMENT '开票人',
  `check_status` tinyint NULL DEFAULT 0 COMMENT '0待审核、1审核中、2审核通过、3审核未通过',
  `flow_id` bigint NULL DEFAULT NULL COMMENT '审核流程ID',
  `step_id` bigint NULL DEFAULT NULL COMMENT '审核步骤ID',
  `check_admin_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '已经审批人IDs',
  `flow_admin_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前需要审批的人',
  `status` tinyint NULL DEFAULT 0 COMMENT '状态0未开票1开票中2已开票3开票失败',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `contract_id`(`contract_id` ASC) USING BTREE,
  INDEX `customer_i`(`customer_id` ASC) USING BTREE,
  INDEX `invoice_admin_id`(`invoice_admin_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '发票表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_invoice
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_message
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_message`;
CREATE TABLE `yshop_crm_message`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `relation_type` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0' COMMENT '关联x类型 examine-审核 customer-客户',
  `relation_id` bigint NULL DEFAULT NULL COMMENT '关联ID',
  `to_user_id` bigint NULL DEFAULT NULL COMMENT '接收人ID',
  `from_user_id` bigint NULL DEFAULT NULL COMMENT '发送人ID',
  `content` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '发送内容',
  `send_time` datetime NULL DEFAULT NULL COMMENT '发送时间',
  `read_time` datetime NULL DEFAULT NULL COMMENT '阅读时间',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '0 未操作 1已操作 ',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 37 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '提醒消息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_message
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_operatelog
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_operatelog`;
CREATE TABLE `yshop_crm_operatelog`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `customer_id` bigint NOT NULL DEFAULT 0 COMMENT '客户ID',
  `contract_id` bigint NOT NULL DEFAULT 0 COMMENT '合同ID',
  `receivable_id` bigint NOT NULL DEFAULT 0 COMMENT '回款ID',
  `nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '姓名',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '管理员账号',
  `url` varchar(1500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '操作页面',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '日志标题',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT 'IP',
  `useragent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'User-Agent',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `customer_id`(`customer_id` ASC) USING BTREE,
  INDEX `contract_id`(`contract_id` ASC) USING BTREE,
  INDEX `receivable_id`(`receivable_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5859 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_operatelog
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_crm_record
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_record`;
CREATE TABLE `yshop_crm_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `types` enum('business','clues','customer') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'customer' COMMENT '关联类型(customer跟进,business商机跟进,clues线索)',
  `types_id` bigint NOT NULL COMMENT '类型ID（根据types变动而变动）',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '跟进内容',
  `record_type` int NOT NULL DEFAULT 0 COMMENT '跟进类型/方式',
  `record_type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '跟进类型标签',
  `next_time` datetime NULL DEFAULT NULL COMMENT '下次联系时间',
  `lng` double(14, 11) NULL DEFAULT NULL COMMENT '经度',
  `lat` double(14, 11) NULL DEFAULT NULL COMMENT '维度',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `record_id`(`id` ASC) USING BTREE,
  INDEX `types`(`types` ASC) USING BTREE,
  INDEX `types_id`(`types_id` ASC) USING BTREE,
  INDEX `record_type`(`record_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 134 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '跟进记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_crm_record
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_material
-- ----------------------------
DROP TABLE IF EXISTS `yshop_material`;
CREATE TABLE `yshop_material`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `creator` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `type` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '类型1、图片；2、视频',
  `group_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '分组ID',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '素材名',
  `url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT '' COMMENT '素材链接',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 97 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '素材库' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of yshop_material
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_material_group
-- ----------------------------
DROP TABLE IF EXISTS `yshop_material_group`;
CREATE TABLE `yshop_material_group`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `creator` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '分组名',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '素材分组' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of yshop_material_group
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_store_product
-- ----------------------------
DROP TABLE IF EXISTS `yshop_store_product`;
CREATE TABLE `yshop_store_product`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '商品id',
  `shop_id` int NULL DEFAULT NULL COMMENT '店铺id用\'',
  `shop_name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '店铺名称',
  `image` varchar(256) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '商品图片',
  `slider_image` varchar(2000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '轮播图',
  `store_name` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '商品名称',
  `store_info` varchar(256) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '商品简介',
  `keyword` varchar(256) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '关键字',
  `bar_code` varchar(15) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '产品条码（一维码）',
  `brand_id` bigint NULL DEFAULT NULL COMMENT '品牌',
  `cate_id` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '分类id',
  `price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商品价格',
  `vip_price` decimal(8, 2) UNSIGNED NULL DEFAULT 0.00 COMMENT '会员价格',
  `ot_price` decimal(8, 2) UNSIGNED NULL DEFAULT 0.00 COMMENT '市场价',
  `postage` decimal(8, 2) UNSIGNED NULL DEFAULT 0.00 COMMENT '邮费',
  `unit_name` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '单位名',
  `sort` smallint NULL DEFAULT 0 COMMENT '排序',
  `sales` mediumint UNSIGNED NULL DEFAULT 0 COMMENT '销量',
  `stock` mediumint UNSIGNED NULL DEFAULT 0 COMMENT '库存',
  `is_show` tinyint(1) NULL DEFAULT 1 COMMENT '状态（0：未上架，1：上架）',
  `is_hot` tinyint(1) NULL DEFAULT 0 COMMENT '是否热卖',
  `is_benefit` tinyint(1) NULL DEFAULT 0 COMMENT '是否优惠',
  `is_best` tinyint(1) NULL DEFAULT 0 COMMENT '是否精品',
  `is_new` tinyint(1) NULL DEFAULT 0 COMMENT '是否新品',
  `description` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '产品描述',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '添加时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `is_postage` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '是否包邮',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  `mer_use` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '商户是否代理 0不可代理1可代理',
  `give_integral` decimal(8, 2) UNSIGNED NULL DEFAULT NULL COMMENT '获得积分',
  `cost` decimal(8, 2) UNSIGNED NULL DEFAULT NULL COMMENT '成本价',
  `is_seckill` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '秒杀状态 0 未开启 1已开启',
  `is_bargain` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '砍价状态 0未开启 1开启',
  `is_good` tinyint(1) NULL DEFAULT 0 COMMENT '是否优品推荐',
  `ficti` mediumint NULL DEFAULT 100 COMMENT '虚拟销量',
  `browse` int NULL DEFAULT 0 COMMENT '浏览量',
  `code_path` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '产品二维码地址(用户小程序海报)',
  `is_sub` tinyint(1) NULL DEFAULT 0 COMMENT '是否单独分佣',
  `temp_id` int NULL DEFAULT 0 COMMENT '运费模板ID',
  `spec_type` tinyint(1) NULL DEFAULT 0 COMMENT '规格 0单 1多',
  `is_integral` tinyint(1) UNSIGNED ZEROFILL NULL DEFAULT NULL COMMENT '是开启积分兑换',
  `integral` int NULL DEFAULT 0 COMMENT '需要多少积分兑换 只在开启积分兑换时生效',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `is_hot`(`is_hot` ASC) USING BTREE,
  INDEX `is_benefit`(`is_benefit` ASC) USING BTREE,
  INDEX `is_best`(`is_best` ASC) USING BTREE,
  INDEX `is_new`(`is_new` ASC) USING BTREE,
  INDEX `toggle_on_sale, is_del`(`deleted` ASC) USING BTREE,
  INDEX `price`(`price` ASC) USING BTREE,
  INDEX `is_show`(`is_show` ASC) USING BTREE,
  INDEX `sort`(`sort` ASC) USING BTREE,
  INDEX `sales`(`sales` ASC) USING BTREE,
  INDEX `add_time`(`create_time` ASC) USING BTREE,
  INDEX `is_postage`(`is_postage` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '商品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of yshop_store_product
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_store_product_attr
-- ----------------------------
DROP TABLE IF EXISTS `yshop_store_product_attr`;
CREATE TABLE `yshop_store_product_attr`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `attr_name` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '属性名',
  `attr_values` varchar(256) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '属性值',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `store_id`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 152 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '商品属性表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of yshop_store_product_attr
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_store_product_attr_result
-- ----------------------------
DROP TABLE IF EXISTS `yshop_store_product_attr_result`;
CREATE TABLE `yshop_store_product_attr_result`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `product_id` bigint UNSIGNED NOT NULL COMMENT '商品ID',
  `result` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '商品属性参数',
  `change_time` datetime NOT NULL COMMENT '上次修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_id`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 110 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '商品属性详情表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of yshop_store_product_attr_result
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_store_product_attr_value
-- ----------------------------
DROP TABLE IF EXISTS `yshop_store_product_attr_value`;
CREATE TABLE `yshop_store_product_attr_value`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `product_id` bigint UNSIGNED NOT NULL COMMENT '商品ID',
  `sku` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '商品属性索引值 (attr_value|attr_value[|....])',
  `stock` int UNSIGNED NOT NULL COMMENT '属性对应的库存',
  `sales` int UNSIGNED NULL DEFAULT 0 COMMENT '销量',
  `price` decimal(8, 2) UNSIGNED NOT NULL COMMENT '属性金额',
  `image` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '图片',
  `unique` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '唯一值',
  `cost` decimal(8, 2) UNSIGNED NOT NULL COMMENT '成本价',
  `bar_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '商品条码',
  `ot_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '原价',
  `weight` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '重量',
  `volume` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '体积',
  `brokerage` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '一级返佣',
  `brokerage_two` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '二级返佣',
  `pink_price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '拼团价',
  `pink_stock` int NOT NULL DEFAULT 0 COMMENT '拼团库存',
  `seckill_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '秒杀价',
  `seckill_stock` int NOT NULL DEFAULT 0 COMMENT '秒杀库存',
  `integral` int(10) UNSIGNED ZEROFILL NULL DEFAULT 0000000000 COMMENT '需要多少积分兑换',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique`(`unique` ASC, `sku` ASC) USING BTREE,
  INDEX `store_id`(`product_id` ASC, `sku` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 209 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '商品属性值表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of yshop_store_product_attr_value
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_store_product_brand
-- ----------------------------
DROP TABLE IF EXISTS `yshop_store_product_brand`;
CREATE TABLE `yshop_store_product_brand`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '品牌编号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '品牌名称',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '品牌图片',
  `sort` int NULL DEFAULT 0 COMMENT '品牌排序',
  `description` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '品牌描述',
  `status` tinyint NOT NULL COMMENT '状态',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '商品品牌' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_store_product_brand
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_store_product_category
-- ----------------------------
DROP TABLE IF EXISTS `yshop_store_product_category`;
CREATE TABLE `yshop_store_product_category`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '分类编号',
  `shop_id` int NULL DEFAULT NULL COMMENT '店铺id用\'',
  `parent_id` bigint NULL DEFAULT 0 COMMENT '父分类编号',
  `shop_name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '店铺名称',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类名称',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类图片',
  `sort` int NULL DEFAULT 0 COMMENT '分类排序',
  `description` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类描述',
  `status` tinyint NOT NULL COMMENT '开启状态',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '商品分类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yshop_store_product_category
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_store_product_rule
-- ----------------------------
DROP TABLE IF EXISTS `yshop_store_product_rule`;
CREATE TABLE `yshop_store_product_rule`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `rule_name` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '规格名称',
  `rule_value` json NOT NULL COMMENT '规格值',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '商品规则值(规格)表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of yshop_store_product_rule
-- ----------------------------

-- ----------------------------
-- Table structure for yshop_wechat_template
-- ----------------------------
DROP TABLE IF EXISTS `yshop_wechat_template`;
CREATE TABLE `yshop_wechat_template`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '模板id',
  `tempkey` char(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '模板编号',
  `name` char(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '模板名',
  `content` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '回复内容',
  `tempid` char(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '模板ID',
  `create_time` datetime NOT NULL COMMENT '添加时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `type` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '类型：template:模板消息 subscribe:订阅消息',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `tempkey`(`tempkey` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '微信模板' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of yshop_wechat_template
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;
